args.command:
cd ~ && cat > search.py <<'EOF'
import workcell, sys
bx, by = 389.03, 266.05
step = 0.25
pts = [(0,0)]
n = 1
while n*step <= 1.4:
    for i in range(-n, n+1):
        for j in (-n, n):
            pts.append((i,j)); pts.append((j,i))
    n += 1
seen=set(); uniq=[]
for p in pts:
    if p not in seen: seen.add(p); uniq.append(p)
for (i,j) in uniq:
    x, y = bx+i*step, by+j*step
    r = workcell.call("robot","insert",x,y)
    print(x, y, r.text[:80], flush=True)
    if r.ok:
        print("SUCCESS offset", x-bx, y-by); sys.exit(0)
print("FAILED")
EOF
python3 search.py

